    ok("!! THE SEARCH IS RESUMABLE goes red alone for a missing proof; a resumed search whose final weights, draws, start value, lost flights or a checkpoint differs; a proof killed at another iteration or resumed from another state; another configuration; resumes recorded wrongly; no draws; and is clean on the real pair", (() => { const mk = (f) => { const a = mkAu(); f(a.proof32); return a; }; const a = mkAu(); a.proof32 = null; const cases = [mk((p) => { p.resumed.finalWeights = w963(0.2); }), mk((p) => { p.resumed.draws += 1; }), mk((p) => { p.resumed.startTrain += 1e-12; }), mk((p) => { p.resumed.lostFlights += 1; }), mk((p) => { p.resumed.checkpoints = [{ iter: 8 }]; }), mk((p) => { p.killedAt = 7; }), mk((p) => { p.resumedFrom = 5; }), mk((p) => { p.config.iters = 13; }), mk((p) => { p.straight.resumes = [4]; }), mk((p) => { p.resumed.resumes = []; }), mk((p) => { p.straight.draws = 0; p.resumed.draws = 0; })]; return only(a, "THE SEARCH IS RESUMABLE") && cases.every((x) => has(x, "THE SEARCH IS RESUMABLE")) && reds(mkAu()).length === 0; })());
