sec("9. ROWS FROM THE MUTATION PASS (survivors turned into rows)");
{
    const au0 = mkAu(), bl = X.bottomLines(au0), line = (p) => bl.find((l) => l.startsWith(p));
    const stS = saves(smooth), straightS = run(smooth);
    ok("!! a smooth score (children are accepted and some by crossover: accepted 4, 6, 9, 11, 13, 15 and crossover 2, 3, 3, 5, 6, 6 at generations 2 to 12) resumed from EVERY state equals the straight search in every field, accepted and crossover counts at the checkpoints included", J(stS.map((s) => [s.accepted, s.crossAccepted])) === "[[4,2],[6,3],[9,3],[11,5],[13,6],[15,6]]" && stS.every((s, i) => { const r = run(smooth, { state: JSON.parse(JSON.stringify(s)) }); return body(r) === body(straightS) && J(r.checkpoints.map((k) => [k.accepted, k.crossAccepted])) === J(straightS.checkpoints.map((k) => [k.accepted, k.crossAccepted])) && r.checkpoints[1].accepted === 15; }));
    ok("!! the crossover child is the registered one: from every saved state but the last the first child flown equals a reference written out in this gate (the first draw below the crossover probability picks crossover, then parent a, then parent b from the others, then one draw per gene choosing a parent's weight when below 0.5, then PS.mutate of 1 to 4 weights at sigma 0.3; otherwise a copy of a drawn parent) to the last digit (every saved state but the last); a population of one never crosses (mu 1 runs, crossover count 0)", stS.slice(0, -1).every((s) => { const t = mkFly(smooth); X.longSearch(26011, "V02", WIP, { ...CAP, flyFn: t.f, state: JSON.parse(JSON.stringify(s)) }); const g = X32.generatorAfter(26011, s.draws), mu = 2; let child; if (g() < 0.5) { const a = Math.floor(g() * mu); let b = Math.floor(g() * (mu - 1)); if (b >= a) b++; const pa = Float32Array.from(s.parents[a].weights), pb = Float32Array.from(s.parents[b].weights); child = new Float32Array(pa.length); for (let k = 0; k < child.length; k++) child[k] = g() < 0.5 ? pa[k] : pb[k]; } else { const a = Math.floor(g() * mu); child = Float32Array.from(s.parents[a].weights); } const ref = PS.mutate(child, 0.3, g, 4); return J(Array.from(t.log[0].w)) === J(Array.from(ref)); }) && (() => { const r = run(smooth, { mu: 1, lambda: 3 }); return r.checkpoints.every((k) => k.crossAccepted === 0) && r.checkpoints[1].accepted > 0; })());
    ok("!! champion refuses an iteration that is not a checkpoint (600, 0, 1800.5) with the 'needs one search' message even when every row is whole", (() => { const ra = [26011, 26012, 26013, 26014].map((q) => ({ seed: q, group: "V02", checkpoints: [600, ...X.CHECKPOINTS].map((iter) => ({ iter, weights: [], trainScore: 0, heldScore: 0.5 })) })); return [600, 0, 1800.5].every((it) => /needs one search for each of the seeds/.test(thr(() => X.champion(ra, it)))) && X.champion(ra, 56).seed === 26011; })());
    ok("!! the lines name the right arms: c02 and q02 once each (c02 first) in the AUDIT, EXTRA POWER and PRICED GAIN lines; the unpenalised gain starts with c02, never the autopilot; NETWORKS NOT BEHIND reads c02, not q02 (c02 0.06 ahead of everything: 0 OF 4; q02 0.06 ahead: 4 OF 4)", /: c02 .*; q02 /.test(line("EXTRA POWER")) && /; q02 /.test(line("PENALISED PRICED GAIN")) && /; q02 [\d.]+ \/ /.test(line("AUDIT")) && (line("PENALISED PRICED GAIN").match(/c02 [+-]/g) || []).length === 1 && (line("PENALISED PRICED GAIN").match(/q02 [+-]/g) || []).length === 1 && /unpenalised priced gain c02 /.test(line("REPORTED")) && !/unpenalised priced gain autopilot/.test(line("REPORTED")) && /NETWORKS NOT BEHIND C02: 0 OF 4/.test(X.verdictOf(mkAu({ c02: 0.06 }))) && /NETWORKS NOT BEHIND C02: 4 OF 4/.test(X.verdictOf(mkAu({ q02: 0.06 }))));
    ok("!! the check texts carry the registered numbers: the ZERO LAW row says within 1e-6; the EVALUATION COUNTS row names the checkpoints after generations 56, 75, 94 and 112; the ACCEPTED COUNTS row is clean for a diversity of exactly 0 (a population that has collapsed) and red for a negative one", (() => { const c = X.checksOf(au0), t = (n) => c.find((r) => r.name.startsWith(n)).text; return /within 1e-6/.test(t("ZERO LAW")) && /generations 56, 75, 94, 112/.test(t("THE EVALUATION COUNTS")); })() && (() => { const x = mkAu(); x.search[1].checkpoints[2].diversity = 0; const y = mkAu(); y.search[1].checkpoints[2].diversity = -1; return X.checksOf(x).every((c) => c.ok) && X.checksOf(y).some((c) => !c.ok && c.name.startsWith("THE ACCEPTED COUNTS")); })());
    ok("!! a short weight vector at checkpoint 56 of a seed that is not the champion turns the 4 SEARCHES row, THE FIRST PARENT row, the champion row and the accepted-counts row red (all lean on the count)", (() => { const x = mkAu(); x.search[2].checkpoints[0].weights = w963(0).slice(1); const r = X.checksOf(x).filter((c) => !c.ok).map((c) => c.name); return r.some((n) => n.startsWith("4 SEARCHES")) && r.some((n) => n.startsWith("THE CHAMPION IS THE BEST")) && r.some((n) => n.startsWith("THE FIRST PARENT")); })());
}
console.log(`\n${fails ? "SOME CHECKS FAILED: " + fails : "all checks pass"}`);
finished = true; if (fails) process.exitCode = 1;
